namespace Tests\Feature;

use App\Enums\AttendanceStatus;
use App\Enums\GradeType;
use App\Enums\Role;
use App\Models\Attendance;
use App\Models\ClassSession;
use App\Models\Course;
use App\Models\CourseEnrollment;
use App\Models\Grade;
use App\Models\Student;
use App\Models\User;
use App\Services\Transcript;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

/*
|---------------------------------------------------------------------------
| کارنامهٔ رسمی چاپی (شماره 37)
|
| سندی است که امضا می‌خورد، پس باید بدون منوی پنل چاپ شود و همهٔ اعدادش
| شمسی و فارسی باشند. سه چیز باید این‌جا اثبات شود:
|   ۱. ریزنمرات، ساعت‌ها و وضعیت قبولی درست از همان محاسبه‌ای می‌آیند که
|      صفحهٔ پرونده نشان می‌دهد — کارنامهٔ چاپی نباید با صفحهٔ آنلاین
|      اختلاف عدد داشته باشد.
|   ۲. دانش‌آموز بدون نمره هم سند می‌گیرد («فاقد سابقه»)، نه خطا.
|   ۳. مجوز در لایهٔ route است: امور مالی و پذیرش و دبیر نباید سند را باز
|      کنند، حتی با آدرس مستقیم.
|
| نمرهٔ قبولی ۱۰ از ۲۰ است (استاندارد آموزشگاه) و در Transcript::PASS_SCORE
| نگهداری می‌شود تا صفحه، سرویس و تست هر سه از یک عدد بخوانند.
*/

class TranscriptTest extends TestCase
{
    use RefreshDatabase;

    /** دورهٔ با ۱۲ جلسهٔ ۹۰ دقیقه‌ای = ۱۸ ساعت برنامه‌ریزی‌شده. */
    private function course(array $attributes = []): Course
    {
        return Course::factory()->create(array_merge([
            'session_count' => 12,
            'session_duration' => 90,
        ], $attributes));
    }

    private function enrolled(Course $course, array $attributes = []): Student
    {
        $student = Student::factory()->create($attributes);

        CourseEnrollment::enroll($student, $course)->confirm();

        return $student;
    }

    private function actingAsRole(Role $role): User
    {
        $user = User::factory()->role($role)->create();

        $this->actingAs($user);

        return $user;
    }

    /** تعداد جلسهٔ حاضر/تأخیرِ یک دانش‌آموز در یک دوره. */
    private function attend(Course $course, Student $student, int $attended, int $absent = 0): void
    {
        for ($i = 0; $i < $attended + $absent; $i++) {
            $session = ClassSession::factory()
                ->at(WeekDayEnum::Saturday->value, 9 * 60, 11 * 60, $i + 1)
                ->create(['course_id' => $course->id]);

            Attendance::recordFor($session, [
                [
                    'student_id' => $student->id,
                    'status' => $i < $attended ? AttendanceStatus::Present : AttendanceStatus::Absent,
                ],
            ]);
        }
    }

    // ── سند ────────────────────────────────────────────────

    public function test_the_transcript_is_printed_without_the_panel_chrome(): void
    {
        $this->actingAsRole(Role::Admin);

        $course = $this->course();
        $student = $this->enrolled($course, ['first_name' => 'زهرا', 'last_name' => 'کریمی']);

        // میانگین وزنی: (۷۵٪ × ۳ + ۸۵٪ × ۵) ÷ ۸ = ۸۱٫۲۵٪ → ۱۶٫۲۵ از ۲۰
        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 15);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 17);

        $response = $this->get(route('students.transcript', $student));

        $expectedNumber = 'TR-'.str_pad((string) $student->id, 6, '0', STR_PAD_LEFT).'-'.jalali_date(now(), 'Y');

        $response->assertOk()
            // منو و سایهٔ پنل روی کاغذ نباید باشند
            ->assertDontSee('drawer')
            ->assertSee('کارنامه رسمی')
            ->assertSee(Setting::academyName())
            ->assertSee(to_persian_digits($expectedNumber))
            ->assertSee($course->title)
            ->assertSee($student->first_name)
            // نمرهٔ نهایی از همان محاسبهٔ وزنی صفحهٔ پرونده
            ->assertSee(to_persian_digits(number_format(16.25, 2)))
            ->assertSee('قبولی')
            // تاریخ صدور به شمسی، نه میلادی
            ->assertSee(jalali_date(now()))
            ->assertSee('امضای دانش‌آموز')
            ->assertSee('امضای مدیر آموزشگاه');
    }

    public function test_a_student_without_any_grade_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Deputy);

        $course = $this->course();
        $student = $this->enrolled($course);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('فاقد سابقه')
            // نبودِ نمره نباید «مردود» نشان دهد: قضاوت بدون سند، اتهام است
            ->assertDontSee('مردود');
    }

    public function test_a_student_without_any_enrollment_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Admin);

        $student = Student::factory()->create();

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('فاقد سابقه');
    }

    // ── ریزنمرات و ساعت‌ها ──────────────────────────────────

    public function test_the_transcript_lists_every_grade_and_the_hours(): void
    {
        $this->actingAsRole(Role::Admin);

        $course = $this->course();
        $student = $this->enrolled($course);

        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 15);
        Grade::record($student, $course, GradeType::Quiz, 'کوییز اول', 16);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 18);

        // دو جلسه حاضر، یک جلسه غیب — ساعت حضور باید همان دو تا را بشمارد
        $this->attend($course, $student, attended: 2, absent: 1);

        $rows = app(Transcript::class)->rows($student);

        $this->assertCount(1, $rows);
        $this->assertEqualsWithDelta(18.0, $rows[0]['hours'], 0.01);
        $this->assertEqualsWithDelta(3.0, $rows[0]['attended_hours'], 0.01);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('تکلیف اول')
            ->assertSee('کوییز اول')
            ->assertSee('پایان‌ترم')
            ->assertSee('۱۵٫۰۰/۲۰٫۰۰')
            ->assertSee('۱۶٫۰۰/۲۰٫۰۰')
            ->assertSee('۱۸٫۰۰/۲۰٫۰۰')
            // ساعت برنامه‌ریزی‌شده و ساعت واقعی حضور، هر دو با ارقام فارسی
            ->assertSee(to_persian_digits(app(Transcript::class)->hoursLabel(18.0)))
            ->assertSee(to_persian_digits(app(Transcript::class)->hoursLabel(3.0)));
    }

    // ── وضعیت قبولی ────────────────────────────────────────

    public function test_a_final_score_below_the_threshold_is_marked_failed(): void
    {
        $this->actingAsRole(Role::Admin);

        $course = $this->course();
        $student = $this->enrolled($course);

        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 8);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 8);

        $rows = app(Transcript::class)->rows($student);

        $this->assertEqualsWithDelta(8.0, $rows[0]['score'], 0.01);
        $this->assertSame('مردود', $rows[0]['status']);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('مردود');
    }

    public function test_a_final_score_at_or_above_the_threshold_is_marked_passed(): void
    {
