```php
/**
 * «فاقد سابقه» یعنی نمره‌ای ثبت نشده، نه اینکه دانش‌آموز مردود است.
 * قضاوت بدون سند، اتهام است؛ پس فقط وقتی نمره هست قبولی/مردود می‌گوییم.
 */
private function status(?float $score, bool $hasGrades): string
{
    if (! $hasGrades || $score === null) {
        return self::STATUS_NO_RECORD; // 'فاقد سابقه'
    }

    return $score >= self::PASS_SCORE ? 'قبولی' : 'مردود';
}
