attendedHours:
```php
/**
 * ساعت واقعی حضور: جلسات حاضر/تأخیر × مدت هر جلسه.
 * جلسهٔ غیبت و جلسهٔ بدون ثبت در ساعت حضور حساب نمی‌شوند.
 */
private function attendedHours(Student $student, Course $course): float
{
    $attended = Attendance::query()
        ->where('student_id', $student->id)
        ->whereHas('classSession', fn ($query) => $query->where('course_id', $course->id))
        ->get()
        ->filter(fn (Attendance $row) => $row->attended())
        ->count();

    return round($attended * $course->session_duration / 60, 2);
}
