summary():
```php
/**
 * جمع کارنامه: میانگین سادهٔ نمرهٔ نهایی دوره‌ها، جمع ساعت‌ها و وضعیت کلی.
 *
 * میانگین دوره‌ها ساده است نه وزنی: وزن دوره درچارت درسی متفاوت است و
 * هیچ‌جا ثبت نشده؛ وزن‌دادن دوباره به نمره‌هایی که خودشان وزنی‌اند،
 * پایان‌ترم را دوباره سنگین می‌کند.
 */
public function summary(Student $student): array
{
    $rows = $this->rows($student);

    $scored = $rows->filter(fn (array $row) => $row['score'] !== null);

    $average = $scored->isEmpty()
        ? null
        : round($scored->avg('score'), 2);

    return [
        'average' => $average,
        'hours' => round($rows->sum('hours'), 2),
        'attended_hours' => round($rows->sum('attended_hours'), 2),
        'status' => $this->overallStatus($rows),
    ];
}

private function overallStatus(Collection $rows): string
{
    if ($rows->every(fn (array $row) => $row['status'] === 'فاقد سابقه')) {
        return 'فاقد سابقه';
    }

    // یک مردود هم برای کل کارنامه کافی است: «قبولی با یک ردی» سندِگمراه‌کننده است
    return $rows->contains(fn (array $row) => $row['status'] === 'مردود') ? 'مردود' : 'قبولی';
}
```
