status():
```php
/**
 * «فاقد سابقه» یعنی نمره‌ای ثبت نشده، نه اینکه دانش‌آموز مردود است.
 * قضاوت بدون سند، اتهام است؛ پس فقط وقتی نمره هست قبولی/مردود می‌گوییم.
 */
private function status(?float $score, bool $hasGrades): string
{
    if (! $hasGrades || $score === null) {
        return self::STATUS_NO_RECORD; // 'فاقد سابقه'
    }

    return $score >= self::PASS_SCORE ? 'قبولی' : 'مردود';
}
```

attendedHours:
```php
/**
 * ساعت واقعی حضور: جلسات حاضر/تأخیر × مدت هر جلسه.
 * جلسهٔ غیبت و جلسهٔ بدون ثبت در ساعت حضور حساب نمی‌شوند.
 */
private function attendedHours(Student $student, Course $course): float
{
    $attended = Attendance::query()
        ->where('student_id', $student->id)
        ->whereHas('classSession', fn ($query) => $query->where('course_id', $course->id))
        ->get()
        ->filter(fn (Attendance $row) => $row->attended())
        ->count();

    return round($attended * $course->session_duration / 60, 2);
}
```

summary():
```php
/**
 * جمع کارنامه: میانگین سادهٔ نمرهٔ نهایی دوره‌ها، جمع ساعت‌ها و وضعیت کلی.
 *
 * میانگین دوره‌ها ساده است نه وزنی: وزن دوره درچارت درسی متفاوت است و
 * هیچ‌جا ثبت نشده؛ وزن‌دادن دوباره به نمره‌هایی که خودشان وزنی‌اند،
 * پایان‌ترم را دوباره سنگین می‌کند.
 */
public function summary(Student $student): array
{
    $rows = $this->rows($student);

    $scored = $rows->filter(fn (array $row) => $row['score'] !== null);

    $average = $scored->isEmpty()
        ? null
        : round($scored->avg('score'), 2);

    return [
        'average' => $average,
        'hours' => round($rows->sum('hours'), 2),
        'attended_hours' => round($rows->sum('attended_hours'), 2),
        'status' => $this->overallStatus($rows),
    ];
}

private function overallStatus(Collection $rows): string
{
    if ($rows->every(fn (array $row) => $row['status'] === 'فاقد سابقه')) {
        return 'فاقد سابقه';
    }

    // یک مردود هم برای کل کارنامه کافی است: «قبولی با یک ردی» سندِگمراه‌کننده است
    return $rows->contains(fn (array $row) => $row['status'] === 'مردود') ? 'مردود' : 'قبولی';
}
```
Careful: `$rows->every(...)` on empty collection returns true → 'فاقد سابقه' ✓ (empty = no record).

